+
+enum ag_command ag_parse_command(const char *text)
+{
+  size_t i;
+
+  if (text == NULL)
+    {
+      return AG_COMMAND_NONE;
+    }
+
+  for (i = 0; i < sizeof(g_phrases) / sizeof(g_phrases[0]); i++)
+    {
+      if (strcmp(text, g_phrases[i].text) == 0)
+        {
+          return g_phrases[i].command;
+        }
+    }
+
+  return AG_COMMAND_NONE;
+}
